-- S3 bucket setting, expiring customer upload links, and lead attachments for SQL Server.
SET XACT_ABORT ON; BEGIN TRANSACTION;
ALTER TABLE [dbo].[TenantAwsConfigurations] ADD [BucketName] NVARCHAR(63) NOT NULL CONSTRAINT [DF_TenantAwsConfigurations_BucketName] DEFAULT('');
CREATE TABLE [dbo].[SalesLeadUploadLinks] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_SalesLeadUploadLinks] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [SalesLeadId] UNIQUEIDENTIFIER NOT NULL, [TokenHash] NVARCHAR(64) NOT NULL, [ExpiresAtUtc] DATETIMEOFFSET NOT NULL, [IsActive] BIT NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, CONSTRAINT [FK_UploadLinks_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]), CONSTRAINT [FK_UploadLinks_Leads] FOREIGN KEY ([SalesLeadId]) REFERENCES [dbo].[SalesLeads]([Id]));
CREATE UNIQUE INDEX [UX_SalesLeadUploadLinks_Id] ON [dbo].[SalesLeadUploadLinks]([Id]); CREATE UNIQUE INDEX [UX_SalesLeadUploadLinks_TokenHash] ON [dbo].[SalesLeadUploadLinks]([TokenHash]); CREATE INDEX [IX_SalesLeadUploadLinks_Tenant] ON [dbo].[SalesLeadUploadLinks]([TenantId]);
CREATE TABLE [dbo].[SalesLeadAttachments] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_SalesLeadAttachments] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [SalesLeadId] UNIQUEIDENTIFIER NOT NULL, [UploadLinkId] UNIQUEIDENTIFIER NOT NULL, [OriginalFileName] NVARCHAR(255) NOT NULL, [ContentType] NVARCHAR(150) NOT NULL, [DeclaredSizeBytes] BIGINT NOT NULL, [StoredSizeBytes] BIGINT NULL, [S3ObjectKey] NVARCHAR(700) NOT NULL, [IsUploaded] BIT NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, [UploadedAtUtc] DATETIMEOFFSET NULL, CONSTRAINT [FK_Attachments_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]), CONSTRAINT [FK_Attachments_Leads] FOREIGN KEY ([SalesLeadId]) REFERENCES [dbo].[SalesLeads]([Id]), CONSTRAINT [FK_Attachments_UploadLinks] FOREIGN KEY ([UploadLinkId]) REFERENCES [dbo].[SalesLeadUploadLinks]([Id]));
CREATE UNIQUE INDEX [UX_SalesLeadAttachments_Id] ON [dbo].[SalesLeadAttachments]([Id]); CREATE INDEX [IX_SalesLeadAttachments_Lead_Latest] ON [dbo].[SalesLeadAttachments]([SalesLeadId],[SerialNo] DESC); CREATE INDEX [IX_SalesLeadAttachments_Tenant] ON [dbo].[SalesLeadAttachments]([TenantId]);
COMMIT TRANSACTION;
